function joint = finalize_oem_joint_own_v1(b)
csRun=b.csRun;pfRun=b.pfRun;
outputFolder=b.folder;mode=b.mode;
%FINALIZE_OBSERVATION_ERROR_JOINT Source IC aggregation; no model or optimizer.
%   Both completed source result manifests are verified before reading MATs.
cs = local_read(csRun,'CS',mode);
pf = local_read(pfRun,'PF',mode);
assert(strcmp(cs.status,pf.status),'JWPE:OEM:Joint','Cannot mix source classes.');
assert(strcmp(cs.identity.codeSHA256,pf.identity.codeSHA256), ...
    'JWPE:OEM:Joint','Reactor results were generated by different code.');
names = cs.cfg.modelNames;
assert(isequal(names,pf.cfg.modelNames),'JWPE:OEM:Joint','Model families differ.');
rows = cell(3,10);
for im=1:3
    name = names{im};
    spec = JWPE_OEM_model_spec_v1_3(name,cs.cfg);
    a = cs.cases.(name);
    b = pf.cases.(name);
    valid = a.best.qualityPass && b.best.qualityPass;
    logLik = a.best.logLik+b.best.logLik;
    n = 100;
    k = 12+2*spec.nError;
    AIC = 2*k-2*logLik;
    AICc = AIC+2*k*(k+1)/(n-k-1);
    BIC = k*log(n)-2*logLik;
    stable = strcmp(a.stability,'STABLE') && strcmp(b.stability,'STABLE');
    rows(im,:) = {name,valid,stable,logLik,k,n,AIC,AICc,BIC,NaN};
end
summary = cell2table(rows,'VariableNames',{'Model','ValidForICComparison', ...
    'StableBothReactors','LogLik','K','N','AIC','AICc','BIC','DeltaAICc'});
summary.DeltaBIC = nan(3,1);
v = summary.ValidForICComparison & isfinite(summary.AICc) & isfinite(summary.BIC);
if any(v)
    summary.DeltaAICc(v) = summary.AICc(v)-min(summary.AICc(v));
    summary.DeltaBIC(v) = summary.BIC(v)-min(summary.BIC(v));
end
joint = struct('status','HISTORICAL_OEM_JOINT_REVIEW_REQUIRED', ...
    'summary',summary,'parameterPooling',false,'scientificPromotion',false, ...
    'csResultSHA256',m1_hash_v1(fullfile(csRun,'result.mat'),'file'), ...
    'pfResultSHA256',m1_hash_v1(fullfile(pfRun,'result.mat'),'file'));
joint.testOnly=strcmp(mode,'test');
if joint.testOnly,joint.status='TEST_ONLY_OEM_JOINT_COMPLETE';end
folder=jwpe_own_output_v1(outputFolder);
jwpe_run_write(folder,'result.mat',joint,'mat',false);
jwpe_run_write(folder,'comparison.csv',summary,'table',false);
names = {'result.mat','comparison.csv'};
records = repmat(struct('File','','Bytes',0,'SHA256',''),2,1);
for i=1:2
    info = dir(fullfile(folder,names{i}));
    records(i) = struct('File',names{i},'Bytes',info.bytes, ...
        'SHA256',m1_hash_v1(fullfile(folder,names{i}),'file'));
end
jwpe_run_write(folder,'manifest.csv',struct2table(records),'table',false);
end

function result = local_read(folder,reactor,mode)
T = readtable(fullfile(folder,'manifest.csv'),'Delimiter',',', ...
    'VariableNamingRule','preserve','TextType','string');
required = ["result.mat","comparison.csv","starts.csv", ...
    "pointwise.csv","phases.csv","summary.json"];
assert(height(T)==6 && isequal(sort(T.File),sort(required.')), ...
    'JWPE:OEM:Manifest','Unexpected completed-result manifest.');
for i=1:height(T)
    assert(~contains(T.File(i),["/","\",".."]), ...
        'JWPE:OEM:Manifest','Manifest filename must be a leaf.');
    file = fullfile(folder,char(T.File(i)));
    info = dir(file);
    assert(isscalar(info) && info.bytes==T.Bytes(i) && ...
        strcmp(m1_hash_v1(file,'file'),T.SHA256(i)), ...
        'JWPE:OEM:Manifest','Completed payload identity mismatch.');
end
q = load(fullfile(folder,'result.mat'),'payload');
result = q.payload;
jwpe_require_source_mode_v1(folder,result,mode);
acceptedStatus=strcmp(result.status,'HISTORICAL_OEM_COMPLETE_REVIEW_REQUIRED');
if strcmp(result.status,'TEST_ONLY_OEM_COMPLETE')
    acceptedStatus=strcmp(mode,'test') && result.testOnly && ~result.productionCertified && ...
        strcmp(result.role,'SYNTHETIC_HISTORICAL_OEM_FUNCTIONAL_TEST') && ...
        strcmp(result.identity.dataClassification,'SYNTHETIC_TEST_ONLY');
end
assert(strcmp(result.reactor,reactor) && result.nObs==50 && ...
    result.horizon_d==145 && ...
    acceptedStatus, ...
    'JWPE:OEM:Joint','Wrong reactor or incomplete historical result.');
end
